package br.com.jucelio.sentinelops.incident;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="incidents") public class Incident {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,length=150) private String title;@Column(length=2000) private String description;@Column(name="service_name",nullable=false,length=120) private String serviceName;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Severity severity;@Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private IncidentStatus status;@Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;@Column(name="updated_at",nullable=false) private Instant updatedAt;protected Incident(){} public Incident(String title,String description,String serviceName,Severity severity){this.title=title;this.description=description;this.serviceName=serviceName;this.severity=severity;this.status=IncidentStatus.OPEN;this.createdAt=Instant.now();this.updatedAt=createdAt;}public Long getId(){return id;}public String getTitle(){return title;}public String getDescription(){return description;}public String getServiceName(){return serviceName;}public Severity getSeverity(){return severity;}public IncidentStatus getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void changeStatus(IncidentStatus status){this.status=status;this.updatedAt=Instant.now();}}
